import json

def render(data):
    payload = json.dumps(data, allow_nan=False).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    return TEMPLATE.replace('__PAYLOAD__', payload)

TEMPLATE = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Solar Cell / Inspection Desk</title>
<style>
:root{--bg:#101a23;--panel:#182630;--ink:#e7edf0;--muted:#9aafba;--line:#30434e;--lime:#cdf47d;--red:#fa967d}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 system-ui,sans-serif}.wrap{max-width:1240px;margin:auto;padding:26px 34px}header{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:0 0 20px;letter-spacing:.09em;font-size:12px}.brand{font-weight:800}.muted,p{color:var(--muted)}.hero{display:grid;grid-template-columns:1.4fr 1fr;gap:60px;padding:40px 0 30px}.eyebrow{text-transform:uppercase;letter-spacing:.16em;color:var(--lime);font-size:11px;font-weight:700}h1{font-size:clamp(35px,5vw,59px);letter-spacing:-.04em;line-height:1.05;margin:14px 0 20px}h2{font-size:25px;line-height:1.2;letter-spacing:-.02em;margin:8px 0 14px}h3{font-size:15px;margin:4px 0}p{margin:8px 0}.note{border-left:3px solid var(--lime);background:var(--panel);padding:24px;align-self:center}.small{font-size:12px;color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:26px}.card,.panel{background:var(--panel);border:1px solid var(--line);padding:20px;border-radius:10px}.value{font-size:31px;letter-spacing:-.03em;color:var(--lime);margin:8px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:24px}.panel{margin-bottom:22px;min-width:0}.grid .panel{margin:0}.controls{display:flex;gap:22px;flex-wrap:wrap;align-items:end;margin:18px 0}label{display:flex;flex-direction:column;gap:6px;font-size:12px;color:var(--muted)}select,button{padding:9px 12px;background:#20333f;color:var(--ink);border:1px solid #536976;border-radius:6px;font:inherit}button{cursor:pointer}input{accent-color:var(--lime)}input[type=range]{width:230px}table{width:100%;border-collapse:collapse;font-size:12px;font-variant-numeric:tabular-nums}td,th{text-align:left;padding:10px 8px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-weight:600}.scroll{overflow:auto;max-height:380px}.matrix{display:grid;grid-template-columns:1fr 1fr;gap:10px}.matrix div{background:#223843;padding:15px}.matrix b{display:block;font-size:29px;color:var(--lime)}.matrix .error b{color:var(--red)}.gallery{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.sample{padding:12px;border:1px solid var(--line);border-radius:8px;background:#101a23}.photo{position:relative;aspect-ratio:1}.photo img{width:100%;height:100%;object-fit:contain}.overlay{position:absolute;inset:0;display:grid;grid-template-columns:repeat(6,1fr);pointer-events:none}.sample b{font-size:13px}.badge{font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:var(--red)}a{color:var(--lime)}details{font-size:13px}summary{cursor:pointer;font-weight:700}li{color:var(--muted);margin:7px 0}.bar{height:9px;background:#354853;border-radius:9px;margin:5px 0 12px;overflow:hidden}.bar i{height:100%;display:block;background:var(--lime)}footer{display:flex;justify-content:space-between;font-size:12px;border-top:1px solid var(--line);padding-top:20px;margin-top:30px;color:var(--muted)}@media(max-width:800px){.hero,.grid{grid-template-columns:1fr;gap:20px}.cards,.gallery{grid-template-columns:repeat(2,1fr)}.wrap{padding:20px}h1{font-size:40px}}
</style><div class="wrap"><header><span class="brand">SOLAR CELL / INSPECTION DESK</span><span class="muted">Computer vision · Research benchmark</span></header>
<section class="hero"><div><div class="eyebrow">Find the cells that need a closer look</div><h1>Screen the image.<br>Inspect the uncertainty.</h1><p>Texture and edge features help prioritize solar-cell images for human inspection. Explore the trade-off between missed defects and unnecessary reviews.</p><p class="small">ELPV · Electroluminescence cell crops · Frozen test split</p></div><div class="note"><h3>A screening score is not a diagnosis.</h3><p>The model sees grayscale electroluminescence images, not ordinary rooftop photographs. Review flags are recommendations; no cell is automatically accepted or rejected.</p><p class="small">Image-level evaluation. Module identities are unavailable, so results may overstate performance on entirely new modules.</p></div></section>
<div class="cards" id="cards"></div><div class="grid"><section class="panel"><div class="eyebrow">Operating point</div><h2>What should enter the review queue?</h2><p class="small" id="chosen"></p><div class="controls"><label for="threshold">Explore score threshold <input type="range" id="threshold" min="0" max="1" step="any"></label><button id="reset">Restore validation threshold</button></div><p id="thresholdNote"></p><div class="matrix" id="matrix"></div><p class="small">Moving the slider explores this test set. It does not change the saved model or count as an independently validated improvement.</p></section><section class="panel"><div class="eyebrow">Generalization checks</div><h2>Where does performance change?</h2><div id="subgroups"></div><h3>Brightness stress test</h3><p class="small">Same held-out images, multiplied by 0.8 or 1.2. The model and threshold stay fixed. This is synthetic stress, not a new dataset.</p><div id="stress"></div></section></div>
<section class="panel"><div class="eyebrow">Inspect the evidence</div><h2>Misses, false alarms, and correct calls</h2><p class="small">Up to four examples per outcome, chosen closest to the original threshold. This is a deliberately difficult gallery, not a random sample. Outcomes remain tied to the saved threshold.</p><div class="controls"><label for="outcome">Original outcome<select id="outcome"><option value="all">All outcomes</option><option value="false_negative">Missed defect</option><option value="false_positive">False alarm</option><option value="true_positive">Correct flag</option><option value="true_negative">Correct low score</option></select></label><label for="celltype">Cell type<select id="celltype"><option value="all">Both types</option><option value="mono">Monocrystalline</option><option value="poly">Polycrystalline</option></select></label><label for="overlay">Sensitivity view<select id="overlay"><option value="off">Original image</option><option value="on">Occlusion sensitivity</option></select></label></div><p class="small">Orange squares mark a positive score drop when that patch is replaced with the image mean. This is model sensitivity, not a crack outline, defect mask, or causal explanation.</p><div class="gallery" id="gallery"></div><p class="small">Images: ELPV dataset authors, CC BY-NC-SA 4.0. Resized previews and optional sensitivity overlays. <a href="https://github.com/zae-bayern/elpv-dataset">Source and attribution</a>.</p></section>
<section class="panel"><div class="eyebrow">Human review workflow</div><h2>Inspection queue</h2><p class="small">All held-out cases are saved as QUEUED. Flags prioritize review; low-score cases remain available for audit. No human decisions have been fabricated. This report is a static snapshot; the command-line review tool writes decisions and notes to SQLite.</p><div class="controls"><label for="queuefilter">Show cases<select id="queuefilter"><option value="all">All cases</option><option value="flagged">Flagged at saved threshold</option><option value="missed">Missed defects (retrospective audit)</option></select></label></div><div class="scroll"><table><thead><tr><th>Cell</th><th>Type</th><th>Score</th><th>Priority</th><th>Status</th><th>Dataset label</th></tr></thead><tbody id="queue"></tbody></table></div></section>
<section class="panel"><details open><summary>Evaluation, model selection, and limitations</summary><div id="method"></div><div class="scroll"><table><thead><tr><th>Feature family</th><th>Regularization C</th><th>Validation average precision</th></tr></thead><tbody id="candidates"></tbody></table></div><ul><li>Only annotation endpoints 0 and 1 are used for supervised training and binary metrics. Intermediate annotations are an exploratory challenge set, not relabeled ground truth.</li><li>Exact decoded-pixel duplicates are removed before splitting. Related cells from a common module may still occur in different splits. Bootstrap intervals resample images and do not account for this clustering.</li><li>Logistic outputs are screening scores and have not been independently calibrated as probabilities. The validation recall target is not a guarantee on new images.</li><li>Training-only feature scaling; model selection and threshold selection use validation only. No refitting or augmentation after selection. Ordinary photographs and field deployment are outside the benchmark.</li></ul><p><a href="metrics.json">Metrics and provenance</a> · <a href="predictions.csv">All predictions</a> · <a href="splits.csv">Split manifest</a> · <a href="review_queue.csv">Queue snapshot</a> · <a href="model.json">Portable model</a></p></details></section><footer><span>Solar-cell inspection · Ehsan Cheraghi</span><span>Code: MIT · Image-derived report: CC BY-NC-SA 4.0</span></footer></div>
<script>const D=__PAYLOAD__,S=D.summary,$=id=>document.getElementById(id),pct=x=>(100*x).toFixed(1)+'%',f=x=>Number(x).toFixed(3),names={true_positive:'Correct flag',false_positive:'False alarm',true_negative:'Correct low score',false_negative:'Missed defect'};
const card=(name,value,sub)=>'<div class="card"><span class="small">'+name+'</span><div class="value">'+value+'</div><span class="small">'+sub+'</span></div>';
$('cards').innerHTML=card('Defect recall',pct(S.test.recall),'Fixed threshold · '+S.test.tp+' found / '+(S.test.tp+S.test.fn)+' labeled defects')+card('Flag precision',pct(S.test.precision),'Share of flags labeled defective')+card('Average precision',f(S.test.ap),'Ranking across all thresholds')+card('Review workload',pct(S.test.review_fraction),'Held-out images flagged');
$('chosen').textContent=S.model.kind+' features · C='+S.model.C+' · validation target: 90% recall. Saved threshold '+f(S.model.threshold)+'.';
let current=S.model.threshold;$('threshold').value=current;
function matrix(){let tp=0,tn=0,fp=0,fn=0;D.test.forEach(r=>{if(r.score>=current){r.label===1?tp++:fp++}else{r.label===1?fn++:tn++}});$('matrix').innerHTML='<div>Correct flags<b>'+tp+'</b></div><div class="error">False alarms<b>'+fp+'</b></div><div class="error">Missed defects<b>'+fn+'</b></div><div>Correct low scores<b>'+tn+'</b></div>';$('thresholdNote').textContent='Threshold '+f(current)+' · Recall '+pct(tp/(tp+fn))+' · Precision '+pct(tp/Math.max(tp+fp,1))+' · Review '+pct((tp+fp)/D.test.length);}
$('threshold').oninput=()=>{current=+$('threshold').value;matrix()};$('reset').onclick=()=>{current=S.model.threshold;$('threshold').value=current;matrix()};
$('subgroups').innerHTML=Object.entries(S.subgroups).map(([k,m])=>'<div class="small">'+k.toUpperCase()+' · '+m.n+' images · recall '+pct(m.recall)+' / precision '+pct(m.precision)+'</div><div class="bar"><i style="width:'+pct(m.recall)+'"></i></div>').join('');
$('stress').innerHTML=Object.entries(S.stress).map(([k,m])=>'<p class="small">'+k.replaceAll('_',' ')+' · recall '+pct(m.recall)+' / precision '+pct(m.precision)+'</p>').join('');
function gallery(){const rows=D.examples.filter(r=>($('outcome').value==='all'||r.outcome===$('outcome').value)&&($('celltype').value==='all'||r.type===$('celltype').value));$('gallery').innerHTML=rows.length?rows.map(r=>{const heat=$('overlay').value==='on'?'<div class="overlay">'+r.sensitivity.flat().map(v=>'<span style="background:rgba(255,95,30,'+Math.min(.7,Math.max(0,v)*4)+')"></span>').join('')+'</div>':'';return '<article class="sample"><div class="photo"><img alt="ELPV '+r.path+'" src="'+r.image+'">'+heat+'</div><div class="badge">'+names[r.outcome]+'</div><b>'+r.path.split('/')[1]+'</b><div class="small">'+r.type+' · label '+r.label+' · score '+f(r.score)+'</div></article>'}).join(''):'<p>No examples match these filters.</p>';}
['outcome','celltype','overlay'].forEach(id=>$(id).onchange=gallery);
function queue(){const filter=$('queuefilter').value;const rows=D.test.filter(r=>filter==='all'||(filter==='flagged'&&r.flagged)||(filter==='missed'&&!r.flagged&&r.label===1)).sort((a,b)=>b.score-a.score);$('queue').innerHTML=rows.map(r=>'<tr><td>'+r.path.split('/')[1]+'</td><td>'+r.type+'</td><td>'+f(r.score)+'</td><td>'+(r.flagged?'FLAGGED':'LOW_SCORE')+'</td><td>QUEUED</td><td>'+r.label+'</td></tr>').join('');}$('queuefilter').onchange=queue;
$('method').innerHTML='<p class="small">Split seed '+S.seed+' · '+S.counts.train+' training / '+S.counts.validation+' validation / '+S.counts.test+' test images. '+S.counts.ambiguous+' intermediate-label images held separately; '+S.ambiguous.flagged+' flagged. '+S.duplicates_removed.length+' exact duplicates removed. '+S.features+' texture-family features.</p><p class="small">Image-stratified bootstrap 95% intervals: recall '+S.bootstrap95.recall.map(pct).join('–')+', precision '+S.bootstrap95.precision.map(pct).join('–')+'. These intervals do not measure deployment uncertainty.</p>';
$('candidates').innerHTML=S.selection.candidates.map(r=>'<tr><td>'+r.kind+'</td><td>'+r.C+'</td><td>'+f(r.validation_ap)+'</td></tr>').join('');matrix();gallery();queue();</script></html>'''
